using Captovix;
int count=0;void Check(bool value,string message){if(!value)throw new Exception(message);count++;Console.WriteLine("PASS: "+message);}
void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}catch(System.IO.InvalidDataException){Check(true,name);return;}throw new Exception("Accepted invalid: "+name);}
var doc=new EditorDocument{OriginalWidth=640,OriginalHeight=480,SourceHash="source"};var session=new EditorSession(doc);var region=new PixelRect(50,60,160,32);var hints=new MockupColors("#FFFFFF","#D94155","#FFFFFF",1);var a=MockupStudio.Create(region,new(0,0,640,480),hints);a.Mockup!.Type=MockupKind.Button;a.Text="Tìm kiếm";a.FontSize=18;a.TextPadding=3;a.TextAlignment=TextAlign.Center;
var original=doc.Serialize();session.Change(d=>MockupStudio.Apply(d,a));Check(session.Document.Version==18,"Mockup upgrades only edited document to schema18");Check(session.Document.SourceHash=="source"&&session.Document.PixelBasePng==null,"Photo source/hash and pixel base remain untouched");Check(doc.Annotations.Single().Mockup!.SourceBounds==region,"Erasure is stored with original physical region");
var saved=session.Document.Serialize();var loaded=EditorDocument.Deserialize(saved);loaded.Validate(640,480,"source");Check(loaded.Annotations.Single().Text=="Tìm kiếm"&&loaded.Annotations.Single().Mockup!.Type==MockupKind.Button,"Vietnamese label and element type persist");Check(loaded.Annotations.Single().FillColor=="#D94155"&&loaded.Annotations.Single().TextColor=="#FFFFFF","Text/button colors persist");
session.Undo();Check(session.Document.Serialize()==original,"Undo add restores exact original document without pixel mutation");session.Redo();Check(session.Document.Serialize()==saved,"Redo restores identical editable mockup");
var edited=session.Document.Annotations.Single().Copy();edited.Text="Tra cứu";edited.FillColor="#2E5FA8";edited.CornerRadius=8;edited.StrokeEnabled=true;edited.Color="#000000";edited.Stroke=2;session.Change(d=>MockupStudio.Apply(d,edited,edited.Id));Check(session.Document.Annotations.Count==1&&session.Document.Annotations[0].Text=="Tra cứu","Editing updates existing element without duplicates");session.Undo();Check(session.Document.Serialize()==saved,"Undo editing restores previous text/color/radius");session.Redo();Check(session.Document.Annotations.Single().FillColor=="#2E5FA8","Redo editing restores new button color");
var snapshot=session.Document.Snapshot();snapshot.Annotations.Single().Mockup!.Background="#000000";Check(session.Document.Annotations.Single().Mockup!.Background=="#FFFFFF","Snapshot has independent mockup metadata");
var selected=session.Document.Annotations.Single();var patch=selected.Mockup!.SourceBounds;selected.Translate(35,20);Check(selected.Mockup.SourceBounds==patch,"Moving body keeps original erasure region anchored");
var packet=AnnotationClipboard.Copy(session.Document,[selected.Id]);var target=new EditorDocument{OriginalWidth=64,OriginalHeight=64};AnnotationClipboard.Paste(target,packet,16,x=>new(x.Left,x.Top,x.Width,x.Height));target.Validate(64,64,"");Check(target.Annotations.Single().Mockup is {EraseOriginal:false},"Paste cannot erase unrelated target screenshot using source coordinates");
var template=CompositionTemplate.From(session.Document);Check(template.Objects.Single().Mockup is {EraseOriginal:false}&&selected.Mockup!.EraseOriginal,"Templates retain editable style without source erasure");
var duplicateIds=AnnotationEditing.Duplicate(session.Document,[selected.Id],x=>new(x.Left,x.Top,x.Width,x.Height));Check(session.Document.Annotations.Single(x=>duplicateIds.Contains(x.Id)).Mockup is {EraseOriginal:false},"Duplicate has no second destructive source mask");
var bad=selected.Copy();bad.Mockup!.SourceBounds=new(-1,0,100,20);Reject(()=>bad.Mockup.Validate(bad,640,480),"Off-image original erasure rejected");bad=selected.Copy();bad.Mockup!.Background="red";Reject(()=>bad.Mockup.Validate(bad,640,480),"Invalid cover color rejected");bad=selected.Copy();bad.Mockup!.Type=(MockupKind)99;Reject(()=>bad.Mockup.Validate(bad,640,480),"Unknown element type rejected");Reject(()=>MockupStudio.Create(new(0,0,7,20),new(0,0,640,480),hints),"Small selection rejected");
Check(MockupStudio.Region(-10,-20,40,30,new(0,0,640,480))==new PixelRect(0,0,40,30),"Drag region uses bounded source pixels");Check(MockupStudio.Region(10,10,160,140,new(30,40,100,80))==new PixelRect(30,40,100,80),"Cropped viewport restricts selection");
var legacy=new EditorDocument{OriginalWidth=100,OriginalHeight=80,Annotations=[new(){Kind=AnnotationKind.Text,Text="Cũ",X2=20,Y2=20}]};legacy.Validate(100,80,"");Check(legacy.Version<18,"Old document does not upgrade when Mockup unused");
int w=100,h=60;var pixels=Enumerable.Repeat((byte)255,w*h*4).ToArray();var button=new PixelRect(10,10,80,40);for(int y=10;y<50;y++)for(int x=10;x<90;x++){int n=(y*w+x)*4;pixels[n]=85;pixels[n+1]=65;pixels[n+2]=217;}for(int y=25;y<33;y++)for(int x=30;x<70;x++){int n=(y*w+x)*4;pixels[n]=pixels[n+1]=pixels[n+2]=255;}
var before=pixels.ToArray();var colors=MockupStudio.Colors(pixels,w,h,button);Check(colors.Background=="#FFFFFF"&&colors.Fill=="#D94155"&&colors.Foreground=="#FFFFFF","Flat page/button/label colors inferred from selected pixels and exterior ring");Check(colors.Flatness==1&&pixels.SequenceEqual(before),"Color suggestion does not modify source pixels");
var invalid=session.Document.Annotations[0].Copy();invalid.FontSize=9999;string checkpoint=session.Document.Serialize();Reject(()=>session.Change(d=>MockupStudio.Apply(d,invalid,invalid.Id)),"Invalid edits fail atomically");Check(session.Document.Serialize()==checkpoint,"Failed apply preserves document and undo state");
var presetTarget=selected.Copy();AnnotationPreset.From("Khung",new(){Kind=AnnotationKind.Ellipse},AnnotationKind.Ellipse).Apply(presetTarget);Check(presetTarget.Kind==AnnotationKind.Rectangle&&presetTarget.Mockup!=null,"Shape presets cannot change mockup object kind");
var box=new AnnotationBox(selected.Left,selected.Top,selected.Width,selected.Height);var limited=ObjectPrecision.LimitResize([selected],box,new(box.X,box.Y,2,2),4,false);Check(limited.Width>=8&&limited.Height>=8,"Resize limits keep mockup valid and editable");
Console.WriteLine(count+" mockup data/undo/color checks passed.");
